def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    # Coordinate compression: every op boundary (l and r + 1) splits the strip.
    pts = {1, n + 1}
    for op in ops:
        if op[0] == 1:
            pts.add(op[1])
            pts.add(op[2] + 1)
        else:
            pts.add(op[1])
            pts.add(op[2] + 1)
    coords = sorted(pts)
    m = len(coords) - 1  # number of elementary segments
    index = {v: i for i, v in enumerate(coords)}

    # Lazy tags: kind 1 = assign(val), kind 2 = chmax(val).
    # Identity is chmax(0), since all colours are >= 0 (0 means blank).
    size = 4 * m
    kind = [2] * size
    val = [0] * size

    def compose(k1, v1, k2, v2):
        # Tag equivalent to applying (k1, v1) first, then (k2, v2).
        if k2 == 1:
            return 1, v2
        if k1 == 1:
            return 1, max(v1, v2)
        return 2, max(v1, v2)

    def push(node):
        nk, nv = kind[node], val[node]
        if nk == 2 and nv == 0:
            return
        for c in (2 * node, 2 * node + 1):
            kind[c], val[c] = compose(kind[c], val[c], nk, nv)
        kind[node], val[node] = 2, 0

    def update(node, lo, hi, l, r, k, v):
        if r < lo or hi < l:
            return
        if l <= lo and hi <= r:
            kind[node], val[node] = compose(kind[node], val[node], k, v)
            return
        push(node)
        mid = (lo + hi) // 2
        update(2 * node, lo, mid, l, r, k, v)
        update(2 * node + 1, mid + 1, hi, l, r, k, v)

    # Apply operations in order.
    for op in ops:
        if op[0] == 1:
            _, l, r, c = op
            k, v = 2, c  # paint: new = max(old, c), blank = 0 takes c
        else:
            _, l, r = op
            k, v = 1, 0  # erase: assign blank
        lo_i = index[l]
        hi_i = index[r + 1] - 1
        update(1, 0, m - 1, lo_i, hi_i, k, v)

    # Push everything down and read the final colour of each elementary segment.
    counts = {}

    def collect(node, lo, hi):
        if lo == hi:
            c = val[node]
            if c > 0:
                length = coords[lo + 1] - coords[lo]
                counts[c] = counts.get(c, 0) + length
            return
        push(node)
        mid = (lo + hi) // 2
        collect(2 * node, lo, mid)
        collect(2 * node + 1, mid + 1, hi)

    collect(1, 0, m - 1)
    return sorted([[c, cnt] for c, cnt in counts.items() if cnt > 0])
